func:
// Function justified: the callback has three structurally different delivery
// envelopes (passthrough, merge, and time-windowed push). Safely normalizing
// those recursive shapes and resolving aggregate values is not maintainable as
// a single declarative JSONata expression.

const CLASS_NAMES = ["car", "person", "truck"];

function parsePayload(value) {
    if (typeof value !== "string") return value;
    try { return JSON.parse(value); }
    catch (err) {
        node.warn("Ignoring non-JSON callback payload: " + err.message);
        return null;
    }
}

function collectSources(value, output, depth) {
    if (depth > 6 || value == null) return;
    if (Array.isArray(value)) {
        for (const item of value) collectSources(item, output, depth + 1);
        return;
    }
    if (typeof value !== "object") return;
    if (value.source_id != null && (value.obj_counter != null || value.analytics_obj_cnt != null || value.objInROIcnt != null)) {
        output.push(value);
        return;
    }
    if (value.data != null) {
        collectSources(value.data, output, depth + 1);
        return;
    }
    for (const child of Object.values(value)) collectSources(child, output, depth + 1);
}

function countValue(value, preferred) {
    if (Number.isFinite(Number(value))) return Number(value);
    if (!value || typeof value !== "object") return 0;
    for (const key of preferred) {
        if (Number.isFinite(Number(value[key]))) return Number(value[key]);
    }
    return 0;
}

function normalizeMap(value, preferred) {
    const result = {};
    if (!value || typeof value !== "object" || Array.isArray(value)) return result;
    for (const [key, raw] of Object.entries(value)) result[key] = countValue(raw, preferred);
    return result;
}

let payload = parsePayload(msg.payload);
if (Array.isArray(payload)) {
    const records = payload.filter((item) => item && typeof item === "object" && item.data != null);
    if (records.length) payload = records[records.length - 1].data;
}

const rawSources = [];
collectSources(payload, rawSources, 0);
if (!rawSources.length) {
    node.warn("Callback payload did not contain AIPV1EMI0001 source metrics");
    return null;
}

const mediaSources = msg.metadata && msg.metadata.mediaSources && typeof msg.metadata.mediaSources === "object"
    ? msg.metadata.mediaSources : {};
const sources = rawSources.map((source) => {
    const id = String(source.source_id);
    const counts = {};
    if (Array.isArray(source.obj_counter)) {
        CLASS_NAMES.forEach((name, index) => { counts[name] = countValue(source.obj_counter[index], ["max_val", "mean_val"]); });
    } else {
        Object.assign(counts, normalizeMap(source.obj_counter, ["max_val", "mean_val", "median_val", "count_val"]));
    }
    const analytics = source.analytics_obj_cnt && typeof source.analytics_obj_cnt === "object"
        ? source.analytics_obj_cnt : {};
    const roi = normalizeMap(analytics.objInROIcnt || source.objInROIcnt, ["max_val", "sum_val"]);
    const lineCrossing = normalizeMap(analytics.objLCCurrCnt || source.objLCCurrCnt, ["max_val", "sum_val"]);
    const total = Object.values(counts).reduce((sum, value) => sum + value, 0);
    return {
        id,
        name: mediaSources[id] && mediaSources[id].name ? mediaSources[id].name : "Source " + id,
        frameFrom: source.frame_number_from != null ? source.frame_number_from : source.frame_num,
        frameTo: source.frame_number_to != null ? source.frame_number_to : source.frame_num,
        counts,
        total,
        roi,
        lineCrossing
    };
});

const totals = { classes: {}, roi: {}, lineCrossing: {}, objects: 0 };
for (const source of sources) {
    totals.objects += source.total;
    for (const [key, value] of Object.entries(source.counts)) totals.classes[key] = (totals.classes[key] || 0) + value;
    for (const [key, value] of Object.entries(source.roi)) totals.roi[key] = (totals.roi[key] || 0) + value;
    for (const [key, value] of Object.entries(source.lineCrossing)) totals.lineCrossing[key] = (totals.lineCrossing[key] || 0) + value;
}

const pipelineId = (msg.metadata && msg.metadata.pipeline && msg.metadata.pipeline.uuid)
    || (msg.eais && msg.eais.pipelineId)
    || env.get("AIP_PIPELINE_ID");
msg.payload = {
    type: "aipv1emi0001.metrics",
    timestamp: new Date().toISOString(),
    aggregation: "latest frame or merge-window maximum",
    pipeline: {
        id: pipelineId || "",
        name: (msg.metadata && msg.metadata.pipeline && msg.metadata.pipeline.name) || ""
    },
    hlsUrl: pipelineId ? "/ms3/pipeline/" + encodeURIComponent(pipelineId) + "/hls" : "",
    sources,
    totals
};
return msg;
